from pathlib import Path
import sys,json,time,numpy as np
from scipy.linalg import cho_factor,cho_solve
p=Path(__file__).resolve().parent;sys.path.insert(0,str(p.parent/'rain-corrected-coupled-reference'));from setup import m,r
scale=np.zeros(r.N)
for block in r.blocks:scale[block['indices']]=1/block['step']
factor=cho_factor(r.S+np.diag(scale),lower=True);rng=np.random.default_rng(20261004);errors=[]
for i in range(24):
 rhs=rng.normal(size=r.N);x=cho_solve(factor,rhs);errors.append(float(max(abs((r.S+np.diag(scale))@x-rhs)/(1+abs(rhs)))))
assert max(errors)<1e-10;(p/'controls.json').write_text(json.dumps(dict(cases=24,maximum_linear_residual=max(errors)),indent=2));results={}
for name,seed in [('cold',np.zeros(r.N)),('capped',m.old[r.remaining].copy())]:
 radii=[r.radius(b,seed) for b in r.blocks]
 def project(y):
  z=y.copy()
  for b,cap in zip(r.blocks,radii):
   ii=b['indices'];domain=b['original']['domain']
   if domain=='positive':z[ii]=np.maximum(y[ii],0)
   elif domain=='box':z[ii]=np.clip(y[ii],-cap,cap)
   elif domain=='ball':z[ii]=y[ii]*min(1.,cap/max(np.linalg.norm(y[ii]),1e-300))
  return z
 def natural(y):return y-project(y-(r.S@y+r.q)/scale)
 z=project(seed);u=np.zeros(r.N);history=[];start=time.monotonic();passed=False
 for iteration in range(1,1025):
  x=cho_solve(factor,scale*(z-u)-r.q);z=project(x+u);u+=x-z
  primal=float(max(abs(x-z)/(1+np.maximum(abs(x),abs(z)))));nr=float(max(abs(natural(z))/(1+abs(z))));feas=float(max(abs(z-project(z))/(1+abs(z))))
  if iteration<=8 or iteration%32==0:history.append(dict(iteration=iteration,natural=nr,primal=primal,feasibility=feas))
  if max(primal,nr,feas)<=1e-8:passed=True;break
 output=dict(status='fixed-bound-pass' if passed else 'fixed-bound-failed',iterations=iteration,seconds=time.monotonic()-start,natural=nr,primal=primal,feasibility=feas,objective=float(.5*z@r.S@z+r.q@z),history=history);results[name]=output;np.savez(p/(name+'.npz'),reduced_impulses=z,full_impulses=r.recover(z),radii=radii);(p/'result.json').write_text(json.dumps(results,indent=2));print(name,json.dumps({k:v for k,v in output.items() if k!='history'}),flush=True)
if not all(x['status']=='fixed-bound-pass' for x in results.values()):raise SystemExit(1)

