blocks=[]
for b in r.blocks:
 d=dict(b['original']);ii=b['indices'];d.update(sl=slice(int(ii[0]),int(ii[-1]+1)),step=b['step'],normal_indices=b['normal_indices']);blocks.append(d)
source=(p.parent/'rain-coupled-reference/structured.py').read_text().split("start=time.monotonic();termination=''")[0].replace('import model as m','');results={}
for name,seed in [('cold',np.zeros(r.N)),('capped',m.old[r.remaining])]:
 out=p/(name+'-clarabel');out.mkdir(exist_ok=True);proxy=types.SimpleNamespace(p=out,H=r.S,g=r.q,old=seed,offset=r.N,E=r.E,blocks=blocks,radius=m.radius,residual=r.residual);ns={'m':proxy};exec(compile(source,'fixed-qp-oracle','exec'),ns);ns['evaluate'](seed[ns['normal_indices']]);ref=ns['states'][0];trial=np.load(p/(name+'.npz'))['reduced_impulses'];obj=lambda z:float(.5*z@r.S@z+r.q@z);reference_obj=obj(ref);results[name]=dict(clarabel=ns['records'][0],reference_objective=reference_obj,admm_objective=obj(trial),objective_gap=obj(trial)-reference_obj,maximum_velocity_difference=float(max(abs(m.M@m.J.T@(r.recover(trial)-r.recover(ref))))));np.savez(out/'reference.npz',impulses=ref)
(p/'qp-comparison.json').write_text(json.dumps(results,indent=2));print(json.dumps(results,indent=2))
